(function(){
'use strict';
var QUICK_FIELDS=['newLesson','oldRevision','recitation','behavior','attendance','homework','tajweed'];
var QUICK_LABELS={newLesson:'الجديد',oldRevision:'الماضي',recitation:'التلاوة',behavior:'السلوك',attendance:'الحضور',homework:'الواجب',tajweed:'التجويد'};
function qesc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(m){return({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[m];});}
function qtoday(){var d=new Date();return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
function qteacher(){return window.currentTeacher||null;}
function qisAdmin(){var t=qteacher();return !!t&&String(t.username||'').trim()==='admin';}
function qowns(c){try{return typeof teacherOwnsClass_==='function'&&teacherOwnsClass_(c);}catch(e){var t=qteacher();return !!t&&(qisAdmin()||String(t.assignedClass||'')===String(c||''));}}
function qdateAllowed(){var t=qteacher();return qisAdmin()||!!(t&&t.quickRegistrationDateEditAllowed===true);}
function qrecordKey(studentId,cls,date){return typeof dailyStableRecordId_==='function'?dailyStableRecordId_(studentId,cls,date):'daily_'+String(studentId)+'_'+String(cls)+'_'+String(date).slice(0,10);}
function qstudentId(name,cls){try{return dailyStudentId_(name,cls);}catch(e){var st=(window.studentsData||[]).find(function(x){return String(x.name||'').trim()===String(name||'').trim()&&String(x.className||'')===String(cls||'');});return st?String(st.studentId||st.id):'legacy_'+String(name)+'_'+String(cls);}}
function qfind(name,cls,date){var sid=qstudentId(name,cls),id=qrecordKey(sid,cls,date),list=window.dailyRecords||[];return list.find(function(r){return !r._deleted&&!r._legacyMigrated&&(String(r.id)===String(id)||(String(r.studentId||'')===String(sid)&&String(r.className||'')===String(cls)&&String(r.dateISO||'').slice(0,10)===String(date).slice(0,10)));})||null;}
function qclasses(){var all=window.ALL_CLASSES||[];var t=qteacher();if(qisAdmin()||String(t&&t.assignedClass||'')==='الكل')return all.slice();return all.filter(function(c){return qowns(c);});}
function qshowTab(){if(qteacher()&&String(qteacher().center||'')==='مشرف')return showMessage('app-msg','التسجيل السريع متاح للمدير والمدرسين فقط.','error');var btn=document.getElementById('quick-registration-tab-btn');if(btn)btn.classList.add('active');document.querySelectorAll('.sidebar-nav .tab-btn').forEach(function(b){if(b!==btn)b.classList.remove('active');});document.querySelectorAll('.tab-content').forEach(function(x){x.classList.remove('active');});var tab=document.getElementById('quick-registration-tab');if(tab)tab.classList.add('active');try{closeMainMenu();}catch(e){} qrender();}
window.openQuickRegistration=function(cls){if(!qowns(cls))return showMessage('app-msg','لا يمكنك الوصول إلى التسجيل السريع لهذا الفصل.','error');var cs=document.getElementById('quickClassSelect');if(cs){cs.value=cls;qstudents();}qshowTab();};
function qstudents(){var cls=(document.getElementById('quickClassSelect')||{}).value||'',sel=document.getElementById('quickStudentSelect'),prev=sel&&sel.value;if(!sel)return;var list=(window.studentsData||[]).filter(function(s){return String(s.className||'')===String(cls);}).sort(function(a,b){return String(a.name||'').localeCompare(String(b.name||''),'ar');});sel.innerHTML='<option value="">اختر الطالب</option>'+list.map(function(s){return '<option value="'+qesc(s.name)+'" data-id="'+qesc(s.studentId||s.id||'')+'">'+qesc(s.name)+'</option>';}).join('');if(prev&&list.some(function(s){return String(s.name)===String(prev);}))sel.value=prev;qload();}
function qsetDate(v){var input=document.getElementById('quickDate');if(!input)return;var d=v||qtoday();if(!qdateAllowed()&&d!==qtoday())d=qtoday();input.value=d;qload();qrenderDateControls();}
function qchangeDate(delta){if(!qdateAllowed())return showMessage('app-msg','ليس لديك صلاحية الرجوع بالتاريخ في التسجيل السريع.','error');var input=document.getElementById('quickDate');var d=new Date((input&&input.value||qtoday())+'T00:00:00');d.setDate(d.getDate()+Number(delta||0));qsetDate(d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'));}
function qrenderDateControls(){var b=document.getElementById('quickDateNav');if(!b)return;b.style.display=qdateAllowed()?'flex':'none';}
function qload(){var cls=(document.getElementById('quickClassSelect')||{}).value||'',name=(document.getElementById('quickStudentSelect')||{}).value||'',date=(document.getElementById('quickDate')||{}).value||qtoday();var r=name?qfind(name,cls,date):null;QUICK_FIELDS.forEach(function(id){var el=document.getElementById('quick-'+id);if(el)el.value=r&&r[id]!==undefined&&r[id]!==null?r[id]:'';});var absent=document.getElementById('quick-absent');if(absent)absent.checked=!!(r&&((r.isAbsent===true)||String(r.attendanceStatus||'')==='absent'));var note=document.getElementById('quick-existing-note');if(note)note.textContent=r?'يوجد تسجيل لهذا الطالب في هذا اليوم. سيتم تحديث نفس السجل عند الحفظ، ولن يُنشأ سجل مكرر.':'لا يوجد تسجيل لهذا الطالب في هذا اليوم.';qcalc();}
function qcalc(){var total=QUICK_FIELDS.reduce(function(sum,id){var v=Number(document.getElementById('quick-'+id)?.value);return sum+(Number.isFinite(v)?Math.max(0,Math.min(10,v)):0);},0);var el=document.getElementById('quick-total');if(el)el.value=total;}
function qclear(){QUICK_FIELDS.forEach(function(id){var el=document.getElementById('quick-'+id);if(el)el.value='';});var a=document.getElementById('quick-absent');if(a)a.checked=false;qcalc();}
window.quickRegistrationToggleAbsent=function(){var a=document.getElementById('quick-absent'),on=!!(a&&a.checked);QUICK_FIELDS.forEach(function(id){var el=document.getElementById('quick-'+id);if(el){el.value=on?'0':'';el.disabled=on;}});if(a&&!on)QUICK_FIELDS.forEach(function(id){var el=document.getElementById('quick-'+id);if(el)el.disabled=false;});qcalc();};
window.quickRegistrationDateChange=function(){var input=document.getElementById('quickDate');var today=qtoday();if(!qdateAllowed()&&input&&input.value!==today){input.value=today;return showMessage('app-msg','هذا المدرس مسموح له بالتسجيل في اليوم الحالي فقط.','error');}qload();};
window.quickRegistrationSave=async function(){try{var cls=(document.getElementById('quickClassSelect')||{}).value||'',name=(document.getElementById('quickStudentSelect')||{}).value||'',date=(document.getElementById('quickDate')||{}).value||qtoday();if(!cls||!name)return showMessage('app-msg','اختر الفصل والطالب أولاً.','error');if(!qowns(cls))return showMessage('app-msg','لا يمكنك التسجيل خارج الفصل المسموح لك به.','error');if(!qdateAllowed()&&date!==qtoday())return showMessage('app-msg','لا يمكنك تسجيل يوم سابق بهذا الحساب.','error');var sid=qstudentId(name,cls),id=qrecordKey(sid,cls,date),old=qfind(name,cls,date),abs=!!document.getElementById('quick-absent')?.checked,now=new Date(),record=Object.assign({},old||{},{id:id,recordId:id,studentId:String(sid),studentName:name,className:cls,dateISO:date,dayName:(typeof updateDayOfWeek==='function'&&date===((document.getElementById('recordDate')||{}).value||''))?((document.getElementById('daySelect')||{}).value||''):['الأحد','الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت'][new Date(date+'T00:00:00').getDay()],teacherName:(qteacher()&&qteacher().username)||'',updatedAt:now.toISOString(),quickRegistration:true});
if(abs){record.attendance=0;record.behavior=0;record.newLesson=0;record.oldRevision=0;record.recitation=0;record.homework=0;record.tajweed=0;record.attendanceStatus='absent';record.isAbsent=true;record.absence=true;record._quickFields=['newLesson','oldRevision','recitation','behavior','attendance','homework','tajweed'];}
else{var bad=[];QUICK_FIELDS.forEach(function(id2){var raw=(document.getElementById('quick-'+id2)||{}).value;if(String(raw||'').trim()==='')bad.push(QUICK_LABELS[id2]);else{var n=Number(raw);if(!Number.isFinite(n)||n<0||n>10)bad.push(QUICK_LABELS[id2]);else record[id2]=n;}});if(bad.length)return showMessage('app-msg','يرجى إدخال الدرجات بشكل صحيح: '+bad.join('، '),'error');record.attendanceStatus='present';record.isAbsent=false;record.absence=false;record._quickFields=QUICK_FIELDS.slice();}
record.total=typeof getDailyTotal==='function'?getDailyTotal(record):QUICK_FIELDS.reduce(function(s,k){return s+Number(record[k]||0);},0);
record._dailyTypeSaved=Object.assign({},record._dailyTypeSaved||{},{new:true,old:true,recitation:true});
if(!(window.useFirebase&&window.db))return showMessage('app-msg','Supabase غير متصل — لم يتم اعتماد التسجيل.','error');
await firebaseWriteRecord_('dailyRecords',id,record,{merge:true});
var idx=(window.dailyRecords||[]).findIndex(function(r){return String(r.id)===String(id);});if(idx>=0)window.dailyRecords[idx]=Object.assign({},window.dailyRecords[idx],record);else(window.dailyRecords||(window.dailyRecords=[])).push(record);try{memoryStorage.setItem('dailyRecords',JSON.stringify(window.dailyRecords));}catch(e){}
try{if(typeof renderDailyTable==='function')renderDailyTable();if(typeof renderManagerView==='function')renderManagerView();if(typeof renderClassStatusTable==='function')renderClassStatusTable();}catch(e){}
qrenderTable();showMessage('app-msg',abs?'تم تسجيل غياب '+name+' في الرصد اليومي بنجاح ✅':'تم حفظ التسجيل السريع لـ '+name+' داخل سجلات الرصد اليومي ✅','success');qload();
}catch(e){console.error('quickRegistrationSave',e);showMessage('app-msg','تعذر حفظ التسجيل السريع: '+(e.message||e),'error');}};
function qrenderTable(){var body=document.querySelector('#quickRegistrationTable tbody');if(!body)return;var cls=(document.getElementById('quickClassSelect')||{}).value||'',date=(document.getElementById('quickDate')||{}).value||'';var list=(window.dailyRecords||[]).filter(function(r){return !r._deleted&&(!cls||String(r.className)===String(cls))&&(!date||String(r.dateISO||'').slice(0,10)===String(date).slice(0,10))&&r.quickRegistration===true&&qowns(r.className);}).sort(function(a,b){return String(a.studentName||'').localeCompare(String(b.studentName||''),'ar');});body.innerHTML=list.length?list.map(function(r){var abs=!!r.isAbsent||String(r.attendanceStatus||'')==='absent';return '<tr><td>'+qesc(r.className)+'</td><td>'+qesc(r.studentName)+'</td><td>'+qesc(r.dateISO)+'</td>'+QUICK_FIELDS.map(function(k){return '<td>'+ (abs&&k!=='attendance'?'-':(r[k]===undefined||r[k]===null||r[k]===''?'-':qesc(r[k]))) +'</td>';}).join('')+'<td><strong>'+qesc(typeof getDailyTotal==='function'?getDailyTotal(r):r.total||0)+'</strong></td></tr>';}).join(''):'<tr><td colspan="11">لا توجد سجلات تسجيل سريع لهذا التاريخ.</td></tr>';}
function qrender(){var cls=document.getElementById('quickClassSelect');if(cls){var cur=cls.value,arr=qclasses();cls.innerHTML=arr.map(function(c){return '<option value="'+qesc(c)+'">'+qesc(c)+'</option>';}).join('');if(arr.indexOf(cur)>=0)cls.value=cur;else if(arr.length)cls.value=arr[0];}var date=document.getElementById('quickDate');if(date&&!date.value)date.value=qtoday();if(date&&!qdateAllowed())date.value=qtoday();qstudents();qrenderDateControls();qrenderTable();}
function installUI(){if(document.getElementById('quick-registration-tab'))return;var side=document.querySelector('.sidebar-nav .tabs');if(!side)return;var dailyBtn=side.querySelector('#daily-tab-btn')||side.querySelector('button[onclick*="daily-tab"]');var btn=document.createElement('button');btn.className='tab-btn';btn.id='quick-registration-tab-btn';btn.type='button';btn.innerHTML='⚡ التسجيل السريع';btn.onclick=qshowTab;if(dailyBtn&&dailyBtn.parentNode)dailyBtn.insertAdjacentElement('afterend',btn);else side.prepend(btn);
var main=document.querySelector('main.content-area');if(!main)return;var tab=document.createElement('div');tab.className='tab-content';tab.id='quick-registration-tab';tab.innerHTML='<div class="card-view"><h3 class="card-title">⚡ التسجيل السريع</h3><div class="quick-registration-note">يسجل هذا القسم في نفس سجلات الرصد اليومي. عند إعادة فتح نفس الطالب والتاريخ ستظهر البيانات المحفوظة وسيتم تحديث نفس السجل بدل إنشاء سجل جديد.</div><div class="quick-registration-toolbar"><div class="form-group"><label>الفصل:</label><select id="quickClassSelect" onchange="quickRegistrationClassChange()"></select></div><div class="form-group"><label>الطالب:</label><select id="quickStudentSelect" onchange="quickRegistrationStudentChange()"></select></div><div class="form-group"><label>التاريخ:</label><div id="quickDateNav" style="display:flex;gap:6px;align-items:center;flex-wrap:wrap"><button class="action-btn btn-warning" type="button" onclick="quickRegistrationChangeDate(-1)">◀ السابق</button><input id="quickDate" type="date" onchange="quickRegistrationDateChange()" style="flex:1;min-width:150px"><button class="action-btn btn-warning" type="button" onclick="quickRegistrationChangeDate(1)">التالي ▶</button><button class="action-btn btn-export" type="button" onclick="quickRegistrationGoToday()">اليوم</button></div></div></div><div id="quick-existing-note" class="quick-registration-note" style="margin-top:12px"></div><div class="form-grid"><div class="quick-registration-absent"><input id="quick-absent" type="checkbox" onchange="quickRegistrationToggleAbsent()"><span>تسجيل الطالب غائب</span></div><div class="form-group"><label>الجديد (10):</label><input id="quick-newLesson" type="number" min="0" max="10" oninput="quickRegistrationRecalc()"></div><div class="form-group"><label>الماضي (10):</label><input id="quick-oldRevision" type="number" min="0" max="10" oninput="quickRegistrationRecalc()"></div><div class="form-group"><label>التلاوة (10):</label><input id="quick-recitation" type="number" min="0" max="10" oninput="quickRegistrationRecalc()"></div><div class="form-group"><label>السلوك (10):</label><input id="quick-behavior" type="number" min="0" max="10" oninput="quickRegistrationRecalc()"></div><div class="form-group"><label>الحضور (10):</label><input id="quick-attendance" type="number" min="0" max="10" oninput="quickRegistrationRecalc()"></div><div class="form-group"><label>الواجب (10):</label><input id="quick-homework" type="number" min="0" max="10" oninput="quickRegistrationRecalc()"></div><div class="form-group"><label>التجويد (10):</label><input id="quick-tajweed" type="number" min="0" max="10" oninput="quickRegistrationRecalc()"></div><div class="form-group"><label>المجموع:</label><input id="quick-total" type="number" readonly></div></div><div class="btn-group"><button class="action-btn btn-save" type="button" onclick="quickRegistrationSave()">💾 حفظ التسجيل</button><button class="action-btn btn-warning" type="button" onclick="quickRegistrationClear()">🧹 تفريغ</button></div></div><div class="card-view quick-registration-table"><h3 class="card-title">📋 سجلات التسجيل السريع</h3><div class="table-responsive"><table id="quickRegistrationTable"><thead><tr><th>الفصل</th><th>الطالب</th><th>التاريخ</th><th>الجديد</th><th>الماضي</th><th>التلاوة</th><th>السلوك</th><th>الحضور</th><th>الواجب</th><th>التجويد</th><th>المجموع</th></tr></thead><tbody></tbody></table></div></div></div>';main.appendChild(tab);
}
window.quickRegistrationClassChange=function(){qstudents();};window.quickRegistrationStudentChange=function(){qload();};window.quickRegistrationRecalc=function(){qcalc();};window.quickRegistrationClear=function(){qclear();};window.quickRegistrationChangeDate=function(d){qchangeDate(d);};window.quickRegistrationGoToday=function(){qsetDate(qtoday());};
function installAdminPermission(){if(!qisAdmin())return;var admin=document.getElementById('admin-tab');if(!admin||document.getElementById('quickRegistrationTeacherPermissions'))return;var card=document.createElement('div');card.className='card-view';card.id='quickRegistrationTeacherPermissions';card.style.borderTop='4px solid var(--primary-color)';card.innerHTML='<h3 class="card-title">⚡ صلاحية الرجوع بالتاريخ في التسجيل السريع</h3><p style="font-size:.88em;color:#666;line-height:1.8;margin-top:-6px">حدد لكل مدرس هل يُسمح له بالرجوع إلى الأيام السابقة في التسجيل السريع. المدرس غير المسموح له يرى اليوم الحالي فقط، مع بقاء صلاحيات الفصول كما هي.</p><div id="quickRegistrationTeacherPermissionsList" style="display:grid;gap:10px"></div><div class="toast-msg" id="quick-registration-permission-msg"></div>';var anchor=document.getElementById('dailyDateEditPermissions');if(anchor&&anchor.closest('.card-view'))anchor.closest('.card-view').insertAdjacentElement('afterend',card);else admin.prepend(card);qrenderTeacherPermissions();}
function qrenderTeacherPermissions(){var box=document.getElementById('quickRegistrationTeacherPermissionsList');if(!box)return;box.innerHTML=(window.teachersData||[]).map(function(t){var disabled=String(t.username||'')==='admin';var allowed=t.quickRegistrationDateEditAllowed===true;return '<div class="quick-registration-permission-row"><strong>'+qesc(t.username)+' — '+qesc(t.assignedClass||'')+'</strong><label><input type="checkbox" '+(allowed?'checked':'')+(disabled?' disabled':'')+' onchange="setQuickRegistrationDatePermission(\''+qesc(String(t.id))+'\',this.checked)"><span>'+ (allowed?'مسموح':'منع')+'</span></label></div>';}).join('');}
window.setQuickRegistrationDatePermission=async function(id,allowed){if(!qisAdmin())return;var t=(window.teachersData||[]).find(function(x){return String(x.id)===String(id);});if(!t)return;t.quickRegistrationDateEditAllowed=!!allowed;t.updatedAt=new Date().toISOString();try{if(window.useFirebase&&window.db)await window.db.collection('teachers').doc(String(t.id)).set({quickRegistrationDateEditAllowed:!!allowed,updatedAt:t.updatedAt},{merge:true});memoryStorage.setItem('teachersData',JSON.stringify(window.teachersData));qrenderTeacherPermissions();showMessage('app-msg','تم تحديث صلاحية '+t.username+' للتسجيل السريع.','success');}catch(e){t.quickRegistrationDateEditAllowed=!allowed;qrenderTeacherPermissions();showMessage('app-msg','تعذر حفظ صلاحية المدرس: '+(e.message||e),'error');}};
function patchClassCards(){document.querySelectorAll('#class-cards-container .class-box').forEach(function(card){if(card.querySelector('.quick-registration-class-card'))return;var h=card.querySelector('h4');if(!h)return;var txt=String(h.textContent||'').replace(/\s*\(.*?\)\s*$/,'').trim();if(!txt||!qowns(txt))return;var wrap=document.createElement('div');wrap.className='quick-registration-class-card';wrap.innerHTML='<button type="button" class="action-btn btn-save quick-registration-launch">⚡ تسجيل سريع - '+qesc(txt)+'</button>';wrap.querySelector('button').onclick=function(){openQuickRegistration(txt);};card.appendChild(wrap);});}
var oldRenderClassCards=window.renderClassCards; if(typeof oldRenderClassCards==='function'){window.renderClassCards=function(){var r=oldRenderClassCards.apply(this,arguments);setTimeout(patchClassCards,0);return r;};}
var oldSwitchTab=window.switchTab; if(typeof oldSwitchTab==='function'){window.switchTab=function(tabId,event){var r=oldSwitchTab.apply(this,arguments);if(tabId==='quick-registration-tab'){qrender();}return r;};}
function boot(){installUI();installAdminPermission();patchClassCards();qrenderDateControls();var obs=document.getElementById('class-cards-container');if(obs){new MutationObserver(function(){patchClassCards();}).observe(obs,{childList:true,subtree:true});}var t=qteacher();if(t&&t.username!=='admin'&&String(t.assignedClass||'')!=='الكل'){var btn=document.getElementById('quick-registration-tab-btn');if(btn)btn.style.display='';}}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
})();
